import { createRenderer } from '@viewstem/svelte';
import Ready from './Ready.svelte';

export async function mountApp(target: HTMLElement, services: {load(): Promise<string>; report(report: unknown): void}) {
  const renderer = createRenderer({
    requestExecutor: async () => ({ status: 200, headers: {}, body: await services.load() }),
  });
  renderer.registry.registerComponentContract({ kind: 'Component', id: 'Ready', spec: {} });
  renderer.registerComponent('Ready', Ready);
  const mounted = await renderer.mount({
    target,
    view: {
      queries: {
        profile: {
          query: {
            sources: {
              profile: {
                datasource: { kind: 'Http', baseUrl: 'https://example.com' },
                request: { method: 'GET', path: '/profile' },
              },
            },
            transform: { input: { '@path': '/sources/profile' } },
          },
        },
      },
      render: { id: 'ready', componentRef: 'Ready' },
    },
  });
  const query = mounted.view.getQuery('profile');
  void mounted.initialComplete.then(async (report) => {
    services.report(report);
    await mounted.whenRendered();
    if (!target.textContent?.includes('Ready')) throw new Error('Ready label was not rendered');
  }).catch((error) => {
    console.error('Completion check failed', error);
  });
  return {
    initialComplete: mounted.initialComplete,
    whenRendered: () => mounted.whenRendered(),
    query,
    dispose: () => renderer.dispose(),
  };
}

