import { createRegistry, createRuntime } from '@viewstem/core';

export async function run(): Promise<string[]> {
  const registry = createRegistry();
  registry.registerComponentContract({ kind: 'Component', id: 'Empty', spec: {} });
  const runtime = createRuntime({ registry });
  try {
    const { view, initialComplete } = await runtime.createView({
      view: {
        states: { value: { kind: 'State', schema: { type: 'string' }, initial: 'one' } },
        render: { id: 'root', componentRef: 'Empty' },
      },
    });
    await initialComplete;
    const state = view.getState('value');
    const read = (): string => {
      const value = state.read();
      if (typeof value !== 'string') throw new Error('Expected a string State value');
      return value;
    };
    const values = [read()];
    const action = {
      ports: {
        target: { kind: 'State' as const, schema: { type: 'string' }, required: true },
        value: { kind: 'Value' as const, schema: { type: 'string' }, required: true as const },
      },
      steps: [{ kind: 'SetState' as const, target: { '@path': '/ports/target' }, value: { '@path': '/ports/value' } }],
    };
    for (const value of ['two', 'three']) {
      await runtime.invokeAction({ owner: view, action, inputs: { target: state, value } });
      values.push(read());
    }
    return values;
  } finally {
    runtime.dispose();
  }
}

