import { createRenderer, type StateHandle } from '@viewstem/svelte';
import FailingDisplay from './FailingDisplay.svelte';
import Screen from './Screen.svelte';

export async function mountApp(target: HTMLElement, services: { report(diagnostic: unknown): void }) {
  const renderer = createRenderer({ onError: diagnostic => services.report(diagnostic) });
  renderer.registerComponents([
    {
      contract: { kind: 'Component', id: 'FailingDisplay', spec: { ports: { value: { kind: 'Value', schema: { type: 'string' }, required: true } } } },
      component: FailingDisplay,
    },
    {
      contract: { kind: 'Component', id: 'Screen', spec: { slots: { body: {} }, events: { update: { schema: { type: 'null' } } } } },
      component: Screen,
    },
  ]);
  try {
    const mounted = await renderer.mount({
      target,
      view: {
        states: { value: { kind: 'State', schema: { type: 'string' }, initial: 'good' } },
        render: {
          id: 'screen', componentRef: 'Screen',
          slots: { body: [{ id: 'display', componentRef: 'FailingDisplay', inputs: { value: { '@path': '/states/value' } } }] },
          on: { update: {
            action: {
              ports: { target: { kind: 'State', schema: { type: 'string' }, required: true } },
              steps: [{ kind: 'SetState', target: { '@path': '/ports/target' }, value: 'bad' }],
            },
            inputs: { target: { '@path': '/states/value' } },
          } },
        },
      },
    });
    await mounted.initialComplete;
    const value = mounted.view.getState('value') as StateHandle<string>;
    return { value, dispose: () => renderer.dispose() };
  } catch (error) {
    await renderer.dispose();
    throw error;
  }
}

import { createRenderer, type StateHandle, type NodeSnapshot } from '@viewstem/svelte';
