import Row from './Row.svelte';

const stringSchema = { type: 'string' } as const;

export async function mountApp(target: HTMLElement, services: { wait: () => Promise<void> }): Promise<{ setItems(items: {id:string}[]): void | Promise<void>; getDraft(id: string): StateHandle<string>; committed: StateHandle<string>; dispose(): void | Promise<void> }> {
  const renderer = createRenderer();
  renderer.registerComponents([
    { contract: { kind: 'Component', id: 'List', spec: { slots: { default: {} } } }, component: List },
    { contract: { kind: 'Component', id: 'Row', spec: { ports: {
      id: { kind: 'Value', schema: stringSchema, required: true },
      value: { kind: 'Value', schema: stringSchema, required: true },
      draft: { kind: 'State', schema: stringSchema, required: true },
    }, events: { commit: { schema: { type: 'object' } } } } }, component: Row },
  ]);
  renderer.registry.registerAction({ kind: 'Action', id: 'Commit', spec: { ports: {
    id: { kind: 'Value', schema: stringSchema, required: true },
    target: { kind: 'State', schema: stringSchema, required: true },
  } } }, async ({ inputs, signal }) => {
    await services.wait();
    if (!signal.aborted) inputs.target.write(inputs.id);
  });
  const mounted = await renderer.mount({ target, view: {
